package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused assignment writes no audit line. */
public class RecordClaimReviewAssigned {
    public void record(@Val ClaimReviewAssign change, @Val Claim claim, People people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record("REVIEW_ASSIGNED sheet=" + claim.getSheetId() + " by=" + change.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + " user=" + change.assignee());
    }
}
EOF
cat > "resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}/review-assign.POST.yml" <<'EOF'
# Assign a REVIEW claim's review to a user. Only a steward assigns it; a blank user is a 400, a claim
# in any other status or anyone else assigning it is a 409, and either writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimReviewAssign
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimReviewAssign
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimReviewAssigned
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused assignment writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimReviewAssigned
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
EOF
